  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    // spot:
    //
    //     [
    //         [
    //             "22814.01",
    //             "22937.42",
    //             "22832.57",
    //             "22937.42",
    //             "3916.58764051",
    //             "0.171199",
    //             "2982.64647063",
    //             "0.130295",
    //             33,
    //             0,
    //             "22877.449915304470460711",
    //             "MINUTE_5",
    //             1659664800000,
    //             1659665099999
    //         ]
    //     ]
    //
    // contract:
    //
    //           [
    //             "84207.02",
    //             "84320.85",
    //             "84207.02",
    //             "84253.83",
    //             "3707.5395",
    //             "44",
    //             "14",
    //             "1740770040000",
    //             "1740770099999",
    //           ],
    //
    ccxt::any ohlcvLength = getArrayLength(ohlcv);
    ccxt::any isContract = isEqual(ohlcvLength, 9);
    if (isTrue(isContract)) {
      return ccxt::list{
          this->safeInteger(ohlcv, 7), this->safeNumber(ohlcv, 2),
          this->safeNumber(ohlcv, 1),  this->safeNumber(ohlcv, 0),
          this->safeNumber(ohlcv, 3),  this->safeNumber(ohlcv, 5)};
    }
    return ccxt::list{this->safeInteger(ohlcv, 12), this->safeNumber(ohlcv, 2),
                      this->safeNumber(ohlcv, 1),   this->safeNumber(ohlcv, 0),
                      this->safeNumber(ohlcv, 3),   this->safeNumber(ohlcv, 5)};
  }

  /**
   * @method
   * @name poloniex#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see https://api-docs.poloniex.com/spot/api/public/market-data#candles
   * @see https://api-docs.poloniex.com/v3/futures/api/market/get-kline-data
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"), std::string("paginate"),
                     false);
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, 500));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("interval"),
                      this->safeString(this->timeframes, timeframe, timeframe)},
                 };
                 ccxt::any keyStart =
                     (isTrue((isEqual(::getValue(market, std::string("spot")),
                                      true)))
                          ? ccxt::any(std::string("startTime"))
                          : ccxt::any(std::string("sTime")));
                 ccxt::any keyEnd =
                     (isTrue((isEqual(::getValue(market, std::string("spot")),
                                      true)))
                          ? ccxt::any(std::string("endTime"))
                          : ccxt::any(std::string("eTime")));
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, keyStart, since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   // limit should in between 100 and 500
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any requestparamsVariable =
                     this->handleUntilOption(keyEnd, request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(isEqual(::getValue(market, std::string("contract")),
                                    true))) {
                   ccxt::any responseRaw =
                       awaitValue(this->swapPublicGetV3MarketCandles(
                           this->extend(request, params)));
                   //
                   //     {
                   //         code: "200",
                   //         msg: "Success",
                   //         data: [
                   //           [
                   //             "84207.02",
                   //             "84320.85",
                   //             "84207.02",
                   //             "84253.83",
                   //             "3707.5395",
                   //             "44",
                   //             "14",
                   //             "1740770040000",
                   //             "1740770099999",
                   //           ],
                   //
                   ccxt::any data =
                       this->safeList(responseRaw, std::string("data"));
                   return this->parseOHLCVs(data, market, timeframe, since,
                                            limit);
                 }
                 ccxt::any response =
                     awaitValue(this->publicGetMarketsSymbolCandles(
                         this->extend(request, params)));
                 //
                 //     [
                 //         [
                 //             "22814.01",
                 //             "22937.42",
                 //             "22832.57",
                 //             "22937.42",
                 //             "3916.58764051",
                 //             "0.171199",
                 //             "2982.64647063",
                 //             "0.130295",
                 //             33,
                 //             0,
                 //             "22877.449915304470460711",
                 //             "MINUTE_5",
                 //             1659664800000,
                 //             1659665099999
                 //         ]
                 //     ]
                 //
                 ccxt::any candles = ccxt::list{};
                 if (isTrue(isArray(response))) {
                   candles = response;
                 }
                 return this->parseOHLCVs(candles, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  std::shared_future<ccxt::any>
  loadMarkets(ccxt::any reload = false,
              ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any markets =
                            awaitValue(Exchange::loadMarkets(reload, params));
                        ccxt::any currenciesByNumericId = this->safeValue(
                            this->options,
                            std::string("currenciesByNumericId"));
                        if (isTrue(isTrue((isEqual(currenciesByNumericId,
                                                   ccxt::any{}))) ||
                                   isTrue(reload))) {
                          ::setValue(this->options,
                                     std::string("currenciesByNumericId"),
                                     this->indexBy(this->currencies,
                                                   std::string("numericId")));
                        }
                        return markets;
                      })
        .share();
  }

  /**
   * @method
   * @name poloniex#fetchMarkets
   * @description retrieves data on all markets for poloniex
   * @see
   * https://api-docs.poloniex.com/spot/api/public/reference-data#symbol-information
   * @see
   * https://api-docs.poloniex.com/v3/futures/api/market/get-all-product-info
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any promises =
                            ccxt::list{this->fetchSpotMarkets(params),
                                       this->fetchSwapMarkets(params)};
                        ccxt::any results = awaitValue(promiseAll(promises));
                        return this->arrayConcat(::getValue(results, 0),
                                                 ::getValue(results, 1));
                      })
        .share();
  }

  virtual std::shared_future<ccxt::any>
  fetchSpotMarkets(ccxt::any params = ccxt::dict{}) {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ccxt::any markets =
                            awaitValue(this->publicGetMarkets(params));
                        //
                        //     [
                        //         {
                        //             "symbol" : "BTS_BTC",
                        //             "baseCurrencyName" : "BTS",
                        //             "quoteCurrencyName" : "BTC",
                        //             "displayName" : "BTS/BTC",
                        //             "state" : "NORMAL",
                        //             "visibleStartTime" : 1659018816626,
                        //             "tradableStartTime" : 1659018816626,
                        //             "symbolTradeLimit" : {
                        //                 "symbol" : "BTS_BTC",
                        //                 "priceScale" : 10,
                        //                 "quantityScale" : 0,
                        //                 "amountScale" : 8,
                        //                 "minQuantity" : "100",
                        //                 "minAmount" : "0.00001",
                        //                 "highestBid" : "0",
                        //                 "lowestAsk" : "0"
                        //             }
                        //         }
                        //     ]
                        //
                        return this->parseMarkets(markets);
                      })
        .share();
  }

