  ccxt::any parseCurrency(ccxt::any currency) override {
    ccxt::any entry = currency;
    ccxt::any id = this->safeString(entry, std::string("coin"));
    ccxt::any code = this->safeCurrencyCode(id);
    ccxt::any networks = ccxt::dict{};
    ccxt::any chains =
        this->safeList(entry, std::string("networkList"), ccxt::list{});
    ccxt::any chainsLength = getArrayLength(chains);
    for (ccxt::any j = 0; isLessThan(j, chainsLength); postFixIncrement(j)) {
      ccxt::any chain = ::getValue(chains, j);
      ccxt::any chainId = this->safeString(chain, std::string("blockchain"));
      ccxt::any networkCode = this->networkIdToCode(chainId, code);
      if (isTrue(!isEqual(networkCode, ccxt::any{}))) {
        ::setValue(
            networks, networkCode,
            ccxt::dict{
                {std::string("info"), chain},
                {std::string("id"), chainId},
                {std::string("name"), ccxt::any{}},
                {std::string("code"), networkCode},
                {std::string("active"), ccxt::any{}},
                {std::string("fee"),
                 this->safeNumber(chain, std::string("withdrawFee"))},
                {std::string("deposit"),
                 this->safeBool(chain, std::string("depositEnable"))},
                {std::string("withdraw"),
                 this->safeBool(chain, std::string("withdrawalEnable"))},
                {std::string("precision"),
                 this->parseNumber(this->parsePrecision(
                     this->safeString(chain, std::string("decimals"))))},
                {std::string("limits"),
                 ccxt::dict{
                     {std::string("withdraw"),
                      ccxt::dict{
                          {std::string("min"),
                           this->safeNumber(chain, std::string("withdrawMin"))},
                          {std::string("max"), ccxt::any{}},
                      }},
                     {std::string("deposit"),
                      ccxt::dict{
                          {std::string("min"), ccxt::any{}},
                          {std::string("max"), ccxt::any{}},
                      }},
                 }},
            });
      }
    }
    return this->safeCurrencyStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("name"), this->safeString(entry, std::string("name"))},
        {std::string("code"), code},
        {std::string("type"), ccxt::any{}},
        {std::string("precision"), ccxt::any{}},
        {std::string("info"), entry},
        {std::string("networks"), networks},
        {std::string("deposit"), ccxt::any{}},
        {std::string("withdraw"), ccxt::any{}},
        {std::string("active"), ccxt::any{}},
        {std::string("fee"), ccxt::any{}},
        {std::string("limits"), ccxt::any{}},
        {std::string("margin"),
         this->safeBool(entry, std::string("supportBorrow"))},
    });
  }

  /**
   * @method
   * @name poloniex#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see https://api-docs.poloniex.com/spot/api/public/market-data#ticker
   * @see https://api-docs.poloniex.com/v3/futures/api/market/get-market-info
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(isEqual(::getValue(market, std::string("contract")),
                                    true))) {
                   ccxt::any tickers = awaitValue(this->fetchTickers(
                       ccxt::list{::getValue(market, std::string("symbol"))},
                       params));
                   return this->safeDict(tickers, symbol);
                 }
                 ccxt::any response =
                     awaitValue(this->publicGetMarketsSymbolTicker24h(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "symbol" : "BTC_USDT",
                 //         "open" : "26053.33",
                 //         "low" : "26053.33",
                 //         "high" : "26798.02",
                 //         "close" : "26447.58",
                 //         "quantity" : "6116.210188",
                 //         "amount" : "161082122.88450926",
                 //         "tradeCount" : "134709",
                 //         "startTime" : "1692784440000",
                 //         "closeTime" : "1692870839630",
                 //         "displayName" : "BTC/USDT",
                 //         "dailyChange" : "0.0151",
                 //         "bid" : "26447.57",
                 //         "bidQuantity" : "0.016313",
                 //         "ask" : "26447.58",
                 //         "askQuantity" : "0.068307",
                 //         "ts" : "1692870845446",
                 //         "markPrice" : "26444.11"
                 //     }
                 //
                 return this->parseTicker(response, market);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchTrades
    //
    //  spot:
    //
    //     {
    //         "id" : "60014521",
    //         "price" : "23162.94",
    //         "quantity" : "0.00009",
    //         "amount" : "2.0846646",
    //         "takerSide" : "SELL",
    //         "ts" : 1659684602042,
    //         "createTime" : 1659684602036
    //     }
    //
    //   swap:
    //
    //     {
    //         "id": "105807376",
    //         "side": "buy",
    //         "px": "84410.57",
    //         "qty": "1",
    //         "amt": "84.41057",
    //         "cT": "1740777563557",
    //     }
    //
    // fetchMyTrades
    //
    //  spot:
    //
    //     {
    //         "id": "32164924331503616",
    //         "symbol": "LINK_USDT",
    //         "accountType": "SPOT",
    //         "orderId": "32164923987566592",
    //         "side": "SELL",
    //         "type": "MARKET",
    //         "matchRole": "TAKER",
    //         "createTime": 1648635115525,
    //         "price": "11",
    //         "quantity": "0.5",
    //         "amount": "5.5",
    //         "feeCurrency": "USDT",
    //         "feeAmount": "0.007975",
    //         "pageId": "32164924331503616",
    //         "clientOrderId": "myOwnId-321"
    //     }
    //
    //  swap:
    //
    //     {
    //         "symbol": "BTC_USDT_PERP",
    //         "trdId": "105813553",
    //         "side": "SELL",
    //         "type": "TRADE",
    //         "mgnMode": "CROSS",
    //         "ordType": "MARKET",
    //         "clOrdId": "polo418912106147315112",
    //         "role": "TAKER",
    //         "px": "84704.9",
    //         "qty": "1",
    //         "cTime": "1740842829430",
    //         "uTime": "1740842829450",
    //         "feeCcy": "USDT",
    //         "feeAmt": "0.04235245",
    //         "deductCcy": "",
    //         "deductAmt": "0",
    //         "feeRate": "0.0005",
    //         "id": "418912106342654592",
    //         "posSide": "BOTH",
    //         "ordId": "418912106147315112",
    //         "qCcy": "USDT",
    //         "value": "84.7049",
    //         "actType": "TRADING"
    //     },
    //
    // fetchOrderTrades (taker trades)
    //
    //     {
    //         "id": "30341456333942784",
    //         "symbol": "LINK_USDT",
    //         "accountType": "SPOT",
    //         "orderId": "30249408733945856",
    //         "side": "BUY",
    //         "type": "LIMIT",
    //         "matchRole": "MAKER",
    //         "createTime": 1648200366864,
    //         "price": "3.1",
    //         "quantity": "1",
    //         "amount": "3.1",
    //         "feeCurrency": "LINK",
    //         "feeAmount": "0.00145",
    //         "pageId": "30341456333942784",
    //         "clientOrderId": ""
    //     }
    //
    ccxt::any id = this->safeStringN(trade, ccxt::list{std::string("id"),
                                                       std::string("tradeID"),
                                                       std::string("trdId")});
    ccxt::any orderId =
        this->safeString2(trade, std::string("orderId"), std::string("ordId"));
    ccxt::any timestamp = this->safeIntegerN(
        trade, ccxt::list{std::string("ts"), std::string("createTime"),
                          std::string("cT"), std::string("cTime")});
    ccxt::any marketId = this->safeString(trade, std::string("symbol"));
    market = this->safeMarket(marketId, market, std::string("_"));
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any side = this->safeStringLower2(trade, std::string("side"),
                                            std::string("takerSide"));
    ccxt::any fee = ccxt::any{};
    ccxt::any priceString =
        this->safeString2(trade, std::string("price"), std::string("px"));
    ccxt::any amountString =
        this->safeString2(trade, std::string("quantity"), std::string("qty"));
    ccxt::any costString =
        this->safeString2(trade, std::string("amount"), std::string("amt"));
    ccxt::any feeCurrencyId = this->safeString2(
        trade, std::string("feeCurrency"), std::string("feeCcy"));
    ccxt::any feeCostString = this->safeString2(trade, std::string("feeAmount"),
                                                std::string("feeAmt"));
    if (isTrue(!isEqual(feeCostString, ccxt::any{}))) {
      ccxt::any feeCurrencyCode = this->safeCurrencyCode(feeCurrencyId);
      fee = ccxt::dict{
          {std::string("cost"), feeCostString},
          {std::string("currency"), feeCurrencyCode},
      };
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"), id},
            {std::string("info"), trade},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("symbol"), symbol},
            {std::string("order"), orderId},
            {std::string("type"),
             this->safeStringLower2(trade, std::string("ordType"),
                                    std::string("type"))},
            {std::string("side"), side},
            {std::string("takerOrMaker"),
             this->safeStringLower2(trade, std::string("matchRole"),
                                    std::string("role"))},
            {std::string("price"), priceString},
            {std::string("amount"), amountString},
            {std::string("cost"), costString},
            {std::string("fee"), fee},
        },
        market);
  }

  /**
   * @method
   * @name poloniex#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see https://api-docs.poloniex.com/spot/api/public/market-data#trades
   * @see https://api-docs.poloniex.com/v3/futures/api/market/get-execution-info
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              limit); // max 1000, for spot & swap
                 }
                 if (isTrue(isEqual(::getValue(market, std::string("contract")),
                                    true))) {
                   ccxt::any response =
                       awaitValue(this->swapPublicGetV3MarketTrades(
                           this->extend(request, params)));
                   //
                   //     {
                   //         code: "200",
                   //         msg: "Success",
                   //         data: [
                   //         {
                   //             id: "105807320", // descending order
                   //             side: "sell",
                   //             px: "84383.93",
                   //             qty: "1",
                   //             amt: "84.38393",
                   //             cT: "1740777074704",
                   //         },
                   //
                   ccxt::any tradesList = this->safeList(
                       response, std::string("data"), ccxt::list{});
                   return this->parseTrades(tradesList, market, since, limit);
                 }
                 ccxt::any trades =
                     awaitValue(this->publicGetMarketsSymbolTrades(
                         this->extend(request, params)));
                 //
                 //     [
                 //         {
                 //             "id" : "60014521",
                 //             "price" : "23162.94",
                 //             "quantity" : "0.00009",
                 //             "amount" : "2.0846646",
                 //             "takerSide" : "SELL",
                 //             "ts" : 1659684602042,
                 //             "createTime" : 1659684602036
                 //         }
                 //     ]
                 //
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  /**
   * @method
   * @name poloniex#fetchMyTrades
   * @description fetch all trades made by the user
   * @see https://api-docs.poloniex.com/spot/api/private/trade#trade-history
   * @see
   * https://api-docs.poloniex.com/v3/futures/api/trade/get-execution-details
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch trades for
   * @param {int} [limit] the maximum number of trades structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch entries for
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {Trade[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=trade-structure}
   */
  std::shared_future<ccxt::any>
  fetchMyTrades(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchMyTrades"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDynamic(
                       std::string("fetchMyTrades"), symbol, since, limit,
                       params));
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchMyTrades"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 ccxt::any isContract = this->inArray(
                     marketType,
                     ccxt::list{std::string("swap"), std::string("future")});
                 ccxt::any request = ccxt::dict{};
                 ccxt::any startKey =
                     (isTrue(isContract) ? ccxt::any(std::string("sTime"))
                                         : ccxt::any(std::string("startTime")));
                 ccxt::any endKey =
                     (isTrue(isContract) ? ccxt::any(std::string("eTime"))
                                         : ccxt::any(std::string("endTime")));
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, startKey, since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 if (isTrue(isTrue(isContract) &&
                            isTrue(!isEqual(symbol, ccxt::any{})))) {
                   ::setValue(request, std::string("symbol"),
                              this->safeString(market, std::string("id")));
                 }
                 ccxt::any requestparamsVariable =
                     this->handleUntilOption(endKey, request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 if (isTrue(isContract)) {
                   ccxt::any raw =
                       awaitValue(this->swapPrivateGetV3TradeOrderTrades(
                           this->extend(request, params)));
                   //
                   //    {
                   //        "code": "200",
                   //        "msg": "",
                   //        "data": [
                   //            {
                   //                "symbol": "BTC_USDT_PERP",
                   //                "trdId": "105813553",
                   //                "side": "SELL",
                   //                "type": "TRADE",
                   //                "mgnMode": "CROSS",
                   //                "ordType": "MARKET",
                   //                "clOrdId": "polo418912106147315112",
                   //                "role": "TAKER",
                   //                "px": "84704.9",
                   //                "qty": "1",
                   //                "cTime": "1740842829430",
                   //                "uTime": "1740842829450",
                   //                "feeCcy": "USDT",
                   //                "feeAmt": "0.04235245",
                   //                "deductCcy": "",
                   //                "deductAmt": "0",
                   //                "feeRate": "0.0005",
                   //                "id": "418912106342654592",
                   //                "posSide": "BOTH",
                   //                "ordId": "418912106147315112",
                   //                "qCcy": "USDT",
                   //                "value": "84.7049",
                   //                "actType": "TRADING"
                   //            },
                   //
                   ccxt::any data =
                       this->safeList(raw, std::string("data"), ccxt::list{});
                   return this->parseTrades(data, market, since, limit);
                 }
                 ccxt::any response = awaitValue(
                     this->privateGetTrades(this->extend(request, params)));
                 //
                 //     [
                 //         {
                 //             "id": "32164924331503616",
                 //             "symbol": "LINK_USDT",
                 //             "accountType": "SPOT",
                 //             "orderId": "32164923987566592",
                 //             "side": "SELL",
                 //             "type": "MARKET",
                 //             "matchRole": "TAKER",
                 //             "createTime": 1648635115525,
                 //             "price": "11",
                 //             "quantity": "0.5",
                 //             "amount": "5.5",
                 //             "feeCurrency": "USDT",
                 //             "feeAmount": "0.007975",
                 //             "pageId": "32164924331503616",
                 //             "clientOrderId": "myOwnId-321"
                 //         }
                 //     ]
                 //
                 ccxt::any result =
                     this->parseTrades(response, market, since, limit);
                 return result;
               })
        .share();
  }

  virtual ccxt::any parseOrderStatus(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("NEW"), std::string("open")},
        {std::string("PARTIALLY_FILLED"), std::string("open")},
        {std::string("FILLED"), std::string("closed")},
        {std::string("PENDING_CANCEL"), std::string("canceled")},
        {std::string("PARTIALLY_CANCELED"), std::string("canceled")},
        {std::string("CANCELED"), std::string("canceled")},
        {std::string("FAILED"), std::string("canceled")},
    };
    return this->safeString(statuses, status, status);
  }

  ccxt::any parseOrder(ccxt::any order,
                       ccxt::any market = ccxt::any{}) override {
    //
    // fetchOpenOrder
    //
    //     {
    //         "id" : "7xxxxxxxxxxxxxxx6",
    //         "clientOrderId" : "",
    //         "symbol" : "ETH_USDT",
    //         "state" : "NEW",
    //         "accountType" : "SPOT",
    //         "side" : "BUY",
    //         "type" : "LIMIT",
    //         "timeInForce" : "GTC",
    //         "quantity" : "0.001",
    //         "price" : "1600",
    //         "avgPrice" : "0",
    //         "amount" : "0",
    //         "filledQuantity" : "0",
    //         "filledAmount" : "0",
    //         "createTime" : 16xxxxxxxxx26,
    //         "updateTime" : 16xxxxxxxxx36
    //     }
    //
    // fetchOpenOrders (and fetchClosedOrders same for contracts)
    //
    //  spot:
    //
    //     {
    //         "id": "24993088082542592",
    //         "clientOrderId": "",
    //         "symbol": "ELON_USDC",
    //         "state": "NEW",
    //         "accountType": "SPOT",
    //         "side": "SELL",
    //         "type": "MARKET",
    //         "timeInForce": "GTC",
    //         "quantity": "1.00",
    //         "price": "0.00",
    //         "avgPrice": "0.00",
    //         "amount": "0.00",
    //         "filledQuantity": "0.00",
    //         "filledAmount": "0.00",
    //         "createTime": 1646925216548,
    //         "updateTime": 1646925216548
    //     }
    //
    //  contract:
    //
    //     {
    //         "symbol": "BTC_USDT_PERP",
    //         "side": "BUY",
    //         "type": "LIMIT",
    //         "ordId": "418890767248232148",
    //         "clOrdId": "polo418890767248232148",
    //         "mgnMode": "CROSS",
    //         "px": "81130.13",
    //         "reduceOnly": false,
    //         "lever": "20",
    //         "state": "NEW",
    //         "source": "WEB",
    //         "timeInForce": "GTC",
    //         "tpTrgPx": "",
    //         "tpPx": "",
    //         "tpTrgPxType": "",
    //         "slTrgPx": "",
    //         "slPx": "",
    //         "slTrgPxType": "",
    //         "avgPx": "0",
    //         "execQty": "0",
    //         "execAmt": "0",
    //         "feeCcy": "",
    //         "feeAmt": "0",
    //         "deductCcy": "0",
    //         "deductAmt": "0",
    //         "stpMode": "NONE", // todo: selfTradePrevention
    //         "cTime": "1740837741523",
    //         "uTime": "1740840846882",
    //         "sz": "1",
    //         "posSide": "BOTH",
    //         "qCcy": "USDT"
    //         "cancelReason": "", // this field can only be in closed orders
    //     },
    //
    // createOrder, editOrder
    //
    //  spot:
    //
    //     {
    //         "id": "29772698821328896",
    //         "clientOrderId": "1234Abc"
    //     }
    //
    //  contract:
    //
    //    {
    //        "ordId":"418876147745775616",
    //        "clOrdId":"polo418876147745775616"
    //    }
    //
    ccxt::any timestamp = this->safeIntegerN(
        order, ccxt::list{std::string("timestamp"), std::string("createTime"),
                          std::string("cTime")});
    if (isTrue(isEqual(timestamp, ccxt::any{}))) {
      timestamp = this->parse8601(this->safeString(order, std::string("date")));
    }
    ccxt::any marketId = this->safeString(order, std::string("symbol"));
    market = this->safeMarket(marketId, market, std::string("_"));
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any resultingTrades =
        this->safeValue(order, std::string("resultingTrades"));
    if (isTrue(!isEqual(resultingTrades, ccxt::any{}))) {
      if (!isTrue(isArray(resultingTrades))) {
        resultingTrades = this->safeValue(
            resultingTrades,
            this->safeString(market, std::string("id"), marketId));
      }
    }
    ccxt::any price = this->safeStringN(order, ccxt::list{std::string("price"),
                                                          std::string("rate"),
                                                          std::string("px")});
    ccxt::any amount =
        this->safeString2(order, std::string("quantity"), std::string("sz"));
    ccxt::any filled = this->safeString2(order, std::string("filledQuantity"),
                                         std::string("execQty"));
    ccxt::any status =
        this->parseOrderStatus(this->safeString(order, std::string("state")));
    ccxt::any side = this->safeStringLower(order, std::string("side"));
    ccxt::any rawType = this->safeString(order, std::string("type"));
    ccxt::any type = this->parseOrderType(rawType);
    ccxt::any id = this->safeStringN(
        order, ccxt::list{std::string("orderNumber"), std::string("id"),
                          std::string("orderId"), std::string("ordId")});
    ccxt::any fee = ccxt::any{};
    ccxt::any feeCurrency = this->safeString2(
        order, std::string("tokenFeeCurrency"), std::string("feeCcy"));
    ccxt::any feeCost = ccxt::any{};
    ccxt::any feeCurrencyCode = ccxt::any{};
    ccxt::any rate = this->safeString(order, std::string("fee"));
    if (isTrue(isEqual(feeCurrency, ccxt::any{}))) {
      feeCurrencyCode =
          (isTrue((isEqual(side, std::string("buy"))))
               ? ccxt::any(::getValue(market, std::string("base")))
               : ccxt::any(::getValue(market, std::string("quote"))));
    } else {
      // poloniex accepts a 30% discount to pay fees in TRX
      feeCurrencyCode = this->safeCurrencyCode(feeCurrency);
      feeCost = this->safeString2(order, std::string("tokenFee"),
                                  std::string("feeAmt"));
    }
    if (isTrue(!isEqual(feeCost, ccxt::any{}))) {
      fee = ccxt::dict{
          {std::string("rate"), rate},
          {std::string("cost"), feeCost},
          {std::string("currency"), feeCurrencyCode},
      };
    }
    ccxt::any clientOrderId = this->safeString2(
        order, std::string("clientOrderId"), std::string("clOrdId"));
    ccxt::any marginMode = this->safeStringLower(order, std::string("mgnMode"));
    ccxt::any reduceOnly = this->safeBool(order, std::string("reduceOnly"));
    ccxt::any leverage = this->safeInteger(order, std::string("lever"));
    ccxt::any hedged = !isEqual(this->safeString(order, std::string("posSide")),
                                std::string("BOTH"));
    return this->safeOrder(
        ccxt::dict{
            {std::string("info"), order},
            {std::string("id"), id},
            {std::string("clientOrderId"), clientOrderId},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("lastTradeTimestamp"),
             this->safeInteger(order, std::string("updateTime"))},
            {std::string("status"), status},
            {std::string("symbol"), symbol},
            {std::string("type"), type},
            {std::string("timeInForce"),
             this->safeString(order, std::string("timeInForce"))},
            {std::string("postOnly"),
             isEqual(rawType, std::string("LIMIT_MAKER"))},
            {std::string("side"), side},
            {std::string("price"), price},
            {std::string("triggerPrice"),
             this->safeString2(order, std::string("triggerPrice"),
                               std::string("stopPrice"))},
            {std::string("cost"),
             this->safeString(order, std::string("execAmt"))},
            {std::string("average"),
             this->safeString2(order, std::string("avgPrice"),
                               std::string("avgPx"))},
            {std::string("amount"), amount},
            {std::string("filled"), filled},
            {std::string("remaining"), ccxt::any{}},
            {std::string("trades"), resultingTrades},
            {std::string("fee"), fee},
            {std::string("marginMode"), marginMode},
            {std::string("reduceOnly"), reduceOnly},
            {std::string("leverage"), leverage},
            {std::string("hedged"), hedged},
        },
        market);
  }

  virtual ccxt::any parseOrderType(ccxt::any status) {
    ccxt::any statuses = ccxt::dict{
        {std::string("MARKET"), std::string("market")},
        {std::string("LIMIT"), std::string("limit")},
        {std::string("LIMIT_MAKER"), std::string("limit")},
        {std::string("STOP-LIMIT"), std::string("limit")},
        {std::string("STOP-MARKET"), std::string("market")},
    };
    return this->safeString(statuses, status, status);
  }

  virtual ccxt::any parseOpenOrders(ccxt::any orders, ccxt::any market,
                                    ccxt::any result) {
    for (ccxt::any i = 0; isLessThan(i, getArrayLength(orders));
         postFixIncrement(i)) {
      ccxt::any order = ::getValue(orders, i);
      ccxt::any extended = this->extend(
          order,
          ccxt::dict{
              {std::string("status"), std::string("open")},
              {std::string("type"), std::string("limit")},
              {std::string("side"), ::getValue(order, std::string("type"))},
              {std::string("price"), ::getValue(order, std::string("rate"))},
          });
      arrayPush(result, this->parseOrder(extended, market));
    }
    return result;
  }

  /**
   * @method
   * @name poloniex#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see https://api-docs.poloniex.com/spot/api/private/order#open-orders
   * @see https://api-docs.poloniex.com/spot/api/private/smart-order#open-orders
   * // trigger orders
   * @see https://api-docs.poloniex.com/v3/futures/api/trade/get-current-orders
   * @param {string} symbol unified market symbol
   * @param {int} [since] the earliest time in ms to fetch open orders for
   * @param {int} [limit] the maximum number of  open orders structures to
   * retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] set true to fetch trigger orders instead
   * of regular orders
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenOrders(ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
                  ccxt::any limit = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = ccxt::any{};
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOpenOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ccxt::any max =
                       (isTrue((isEqual(marketType, std::string("spot"))))
                            ? ccxt::any(2000)
                            : ccxt::any(100));
                   ::setValue(request, std::string("limit"),
                              mathMax(limit, max));
                 }
                 ccxt::any isTrigger = this->safeValue2(
                     params, std::string("trigger"), std::string("stop"));
                 params = this->omit(params, ccxt::list{std::string("trigger"),
                                                        std::string("stop")});
                 ccxt::any response = ccxt::list{};
                 if (isTrue(!isEqual(marketType, std::string("spot")))) {
                   ccxt::any raw =
                       awaitValue(this->swapPrivateGetV3TradeOrderOpens(
                           this->extend(request, params)));
                   //
                   //    {
                   //        "code": "200",
                   //        "msg": "",
                   //        "data": [
                   //            {
                   //                "symbol": "BTC_USDT_PERP",
                   //                "side": "BUY",
                   //                "type": "LIMIT",
                   //                "ordId": "418890767248232148",
                   //                "clOrdId": "polo418890767248232148",
                   //                "mgnMode": "CROSS",
                   //                "px": "81130.13",
                   //                "reduceOnly": false,
                   //                "lever": "20",
                   //                "state": "NEW",
                   //                "source": "WEB",
                   //                "timeInForce": "GTC",
                   //                "tpTrgPx": "",
                   //                "tpPx": "",
                   //                "tpTrgPxType": "",
                   //                "slTrgPx": "",
                   //                "slPx": "",
                   //                "slTrgPxType": "",
                   //                "avgPx": "0",
                   //                "execQty": "0",
                   //                "execAmt": "0",
                   //                "feeCcy": "",
                   //                "feeAmt": "0",
                   //                "deductCcy": "0",
                   //                "deductAmt": "0",
                   //                "stpMode": "NONE",
                   //                "cTime": "1740837741523",
                   //                "uTime": "1740840846882",
                   //                "sz": "1",
                   //                "posSide": "BOTH",
                   //                "qCcy": "USDT"
                   //            },
                   //
                   response =
                       this->safeList(raw, std::string("data"), ccxt::list{});
                 } else if (isTrue(isEqual(isTrigger, true))) {
                   response = awaitValue(this->privateGetSmartorders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->privateGetOrders(this->extend(request, params)));
                 }
                 //
                 //     [
                 //         {
                 //             "id" : "7xxxxxxxxxxxxxxx6",
                 //             "clientOrderId" : "",
                 //             "symbol" : "ETH_USDT",
                 //             "state" : "NEW",
                 //             "accountType" : "SPOT",
                 //             "side" : "BUY",
                 //             "type" : "LIMIT",
                 //             "timeInForce" : "GTC",
                 //             "quantity" : "0.001",
                 //             "price" : "1600",
                 //             "avgPrice" : "0",
                 //             "amount" : "0",
                 //             "filledQuantity" : "0",
                 //             "filledAmount" : "0",
                 //             "stopPrice": "3750.00",              // for
                 //             trigger orders "createTime" : 16xxxxxxxxx26,
                 //             "updateTime" : 16xxxxxxxxx36
                 //         }
                 //     ]
                 //
                 ccxt::any extension = ccxt::dict{
                     {std::string("status"), std::string("open")},
                 };
                 return this->parseOrders(response, market, since, limit,
                                          extension);
               })
        .share();
  }

  /**
   * @method
   * @name poloniex#fetchClosedOrders
   * @see https://api-docs.poloniex.com/v3/futures/api/trade/get-order-history
   * @description fetches information on multiple closed orders made by the user
   * @param {string} symbol unified market symbol of the market orders were made
   * in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest entry
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any> fetchClosedOrders(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        awaitValue(this->loadMarkets());
                        ccxt::any market = ccxt::any{};
                        ccxt::any request = ccxt::dict{};
                        if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                          market = this->market(symbol);
                          ::setValue(request, std::string("symbol"),
                                     ::getValue(market, std::string("id")));
                        }
                        ccxt::any marketType = ccxt::any{};
                        ccxt::any marketTypeparamsVariable =
                            this->handleMarketTypeAndParams(
                                std::string("fetchClosedOrders"), market,
                                params, std::string("swap"));
                        marketType = ::getValue(marketTypeparamsVariable, 0);
                        params = ::getValue(marketTypeparamsVariable, 1);
                        if (isTrue(isEqual(marketType, std::string("spot")))) {
                          throw NotSupported(toString(add(
                              this->id,
                              std::string(" fetchClosedOrders() is not "
                                          "supported for spot markets yet"))));
                        }
                        if (isTrue(!isEqual(limit, ccxt::any{}))) {
                          ::setValue(request, std::string("limit"),
                                     mathMin(200, limit));
                        }
                        if (isTrue(!isEqual(since, ccxt::any{}))) {
                          ::setValue(request, std::string("sTime"), since);
                        }
                        ccxt::any requestparamsVariable =
                            this->handleUntilOption(std::string("eTime"),
                                                    request, params);
                        request = ::getValue(requestparamsVariable, 0);
                        params = ::getValue(requestparamsVariable, 1);
                        ccxt::any response =
                            awaitValue(this->swapPrivateGetV3TradeOrderHistory(
                                this->extend(request, params)));
                        //
                        //    {
                        //        "code": "200",
                        //        "msg": "",
                        //        "data": [
                        //            {
                        //                "symbol": "BTC_USDT_PERP",
                        //                "side": "SELL",
                        //                "type": "MARKET",
                        //                "ordId": "418912106147315712",
                        //                "clOrdId": "polo418912106147315712",
                        //                "mgnMode": "CROSS",
                        //                "px": "0",
                        //                "sz": "2",
                        //                "lever": "20",
                        //                "state": "FILLED",
                        //                "cancelReason": "",
                        //                "source": "WEB",
                        //                "reduceOnly": "true",
                        //                "timeInForce": "GTC",
                        //                "tpTrgPx": "",
                        //                "tpPx": "",
                        //                "tpTrgPxType": "",
                        //                "slTrgPx": "",
                        //                "slPx": "",
                        //                "slTrgPxType": "",
                        //                "avgPx": "84705.56",
                        //                "execQty": "2",
                        //                "execAmt": "169.41112",
                        //                "feeCcy": "USDT",
                        //                "feeAmt": "0.08470556",
                        //                "deductCcy": "0",
                        //                "deductAmt": "0",
                        //                "stpMode": "NONE",
                        //                "cTime": "1740842829116",
                        //                "uTime": "1740842829130",
                        //                "posSide": "BOTH",
                        //                "qCcy": "USDT"
                        //            },
                        //
                        ccxt::any data = this->safeList(
                            response, std::string("data"), ccxt::list{});
                        return this->parseOrders(data, market, since, limit);
                      })
        .share();
  }

  /**
   * @method
   * @name poloniex#createOrder
   * @description create a trade order
   * @see https://api-docs.poloniex.com/spot/api/private/order#create-order
   * @see
   * https://api-docs.poloniex.com/spot/api/private/smart-order#create-order  //
   * trigger orders
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] the price at which a trigger order is
   * triggered at
   * @param {float} [params.cost] *spot market buy only* the quote quantity that
   * can be used as an alternative for the amount
   * @param {string} [params.clientOrderId] a unique identifier for the order
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                     {std::string("side"), toUpperCase(side)},
                 };
                 ccxt::any triggerPrice =
                     this->safeNumber2(params, std::string("stopPrice"),
                                       std::string("triggerPrice"));
                 ccxt::any requestparamsVariable = this->orderRequest(
                     symbol, type, side, amount, request, price, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = ccxt::dict{};
                 if (isTrue(
                         isTrue((isEqual(
                             ::getValue(market, std::string("swap")), true))) ||
                         isTrue(
                             (isEqual(::getValue(market, std::string("future")),
                                      true))))) {
                   ccxt::any responseInitial =
                       awaitValue(this->swapPrivatePostV3TradeOrder(
                           this->extend(request, params)));
                   //
                   // {"code":200,"msg":"Success","data":{"ordId":"418876147745775616","clOrdId":"polo418876147745775616"}}
                   //
                   response = this->safeDict(responseInitial,
                                             std::string("data"), ccxt::dict{});
                 } else if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   response = awaitValue(this->privatePostSmartorders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->privatePostOrders(this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "id" : "78923648051920896",
                 //         "clientOrderId" : ""
                 //     }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  virtual ccxt::any orderRequest(ccxt::any symbol, ccxt::any type,
                                 ccxt::any side, ccxt::any amount,
                                 ccxt::any request,
                                 ccxt::any price = ccxt::any{},
                                 ccxt::any params = ccxt::dict{}) {
    ccxt::any triggerPrice = this->safeNumber2(params, std::string("stopPrice"),
                                               std::string("triggerPrice"));
    ccxt::any market = this->market(symbol);
    if (isTrue(isEqual(::getValue(market, std::string("contract")), true))) {
      ccxt::any marginMode = ccxt::any{};
      ccxt::any marginModeparamsVariable =
          this->handleParamString(params, std::string("marginMode"));
      marginMode = ::getValue(marginModeparamsVariable, 0);
      params = ::getValue(marginModeparamsVariable, 1);
      if (isTrue(!isEqual(marginMode, ccxt::any{}))) {
        this->checkRequiredArgument(
            std::string("createOrder"), marginMode, std::string("marginMode"),
            ccxt::list{std::string("cross"), std::string("isolated")});
        ::setValue(request, std::string("mgnMode"), toUpperCase(marginMode));
      }
      ccxt::any hedged = ccxt::any{};
      ccxt::any hedgedparamsVariable =
          this->handleParamString(params, std::string("hedged"));
      hedged = ::getValue(hedgedparamsVariable, 0);
      params = ::getValue(hedgedparamsVariable, 1);
      if (isTrue(isTrue((!isEqual(hedged, ccxt::any{}))) &&
                 isTrue((!isEqual(hedged, std::string("")))))) {
        if (isTrue(isEqual(marginMode, ccxt::any{}))) {
          throw ArgumentsRequired(toString(
              add(this->id,
                  std::string(" createOrder() requires a marginMode parameter "
                              "\"cross\" or \"isolated\" for hedged orders"))));
        }
        if (!isTrue((inOp(params, std::string("posSide"))))) {
          throw ArgumentsRequired(toString(
              add(this->id,
                  std::string(" createOrder() requires a posSide parameter "
                              "\"LONG\" or \"SHORT\" for hedged orders"))));
        }
      }
    }
    ccxt::any upperCaseType = toUpperCase(type);
    ccxt::any isMarket = isEqual(upperCaseType, std::string("MARKET"));
    ccxt::any isPostOnly = this->isPostOnly(
        isMarket, isEqual(upperCaseType, std::string("LIMIT_MAKER")), params);
    params = this->omit(params, ccxt::list{std::string("postOnly"),
                                           std::string("triggerPrice"),
                                           std::string("stopPrice")});
    if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
      if (isTrue(!isEqual(::getValue(market, std::string("spot")), true))) {
        throw InvalidOrder(toString(add(
            add(add(this->id,
                    std::string(
                        " createOrder() does not support trigger orders for ")),
                ::getValue(market, std::string("type"))),
            std::string(" markets"))));
      }
      upperCaseType = (isTrue((isEqual(price, ccxt::any{})))
                           ? ccxt::any(std::string("STOP"))
                           : ccxt::any(std::string("STOP_LIMIT")));
      ::setValue(request, std::string("stopPrice"), triggerPrice);
    } else if (isTrue(isPostOnly)) {
      upperCaseType = std::string("LIMIT_MAKER");
    }
    ::setValue(request, std::string("type"), upperCaseType);
    if (isTrue(isMarket)) {
      if (isTrue(isEqual(side, std::string("buy")))) {
        ccxt::any quoteAmount = ccxt::any{};
        ccxt::any createMarketBuyOrderRequiresPrice = true;
        ccxt::any createMarketBuyOrderRequiresPriceparamsVariable =
            this->handleOptionAndParams(
                params, std::string("createOrder"),
                std::string("createMarketBuyOrderRequiresPrice"), true);
        createMarketBuyOrderRequiresPrice =
            ::getValue(createMarketBuyOrderRequiresPriceparamsVariable, 0);
        params = ::getValue(createMarketBuyOrderRequiresPriceparamsVariable, 1);
        ccxt::any cost = this->safeNumber(params, std::string("cost"));
        params = this->omit(params, std::string("cost"));
        if (isTrue(!isEqual(cost, ccxt::any{}))) {
          quoteAmount = this->costToPrecision(symbol, cost);
        } else if (isTrue(
                       isTrue(createMarketBuyOrderRequiresPrice) &&
                       isTrue((isEqual(::getValue(market, std::string("spot")),
                                       true))))) {
          if (isTrue(isEqual(price, ccxt::any{}))) {
            throw InvalidOrder(toString(add(
                this->id,
                std::string(" createOrder() requires the price argument for "
                            "market buy orders to calculate the total cost to "
                            "spend (amount * price), alternatively set the "
                            "createMarketBuyOrderRequiresPrice option or param "
                            "to false and pass the cost to spend (quote "
                            "quantity) in the amount argument"))));
          } else {
            ccxt::any amountString = this->numberToString(amount);
            ccxt::any priceString = this->numberToString(price);
            ccxt::any costRequest =
                ccxt::Precise::stringMul(amountString, priceString);
            quoteAmount = this->costToPrecision(symbol, costRequest);
          }
        } else {
          quoteAmount = this->costToPrecision(symbol, amount);
        }
        ccxt::any amountKey =
            (isTrue((isEqual(::getValue(market, std::string("spot")), true)))
                 ? ccxt::any(std::string("amount"))
                 : ccxt::any(std::string("sz")));
        ::setValue(request, amountKey, quoteAmount);
      } else {
        ccxt::any amountKey =
            (isTrue((isEqual(::getValue(market, std::string("spot")), true)))
                 ? ccxt::any(std::string("quantity"))
                 : ccxt::any(std::string("sz")));
        ::setValue(request, amountKey, this->amountToPrecision(symbol, amount));
      }
    } else {
      ccxt::any amountKey =
          (isTrue((isEqual(::getValue(market, std::string("spot")), true)))
               ? ccxt::any(std::string("quantity"))
               : ccxt::any(std::string("sz")));
      ::setValue(request, amountKey, this->amountToPrecision(symbol, amount));
      ccxt::any priceKey =
          (isTrue((isEqual(::getValue(market, std::string("spot")), true)))
               ? ccxt::any(std::string("price"))
               : ccxt::any(std::string("px")));
      ::setValue(request, priceKey, this->priceToPrecision(symbol, price));
    }
    ccxt::any clientOrderId = this->safeString2(
        params, std::string("clientOrderId"), std::string("clOrdId"));
    if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
      // the futures v3 api silently ignores the spot key and generates its own
      // id
      ccxt::any clientOrderIdKey =
          (isTrue((isEqual(::getValue(market, std::string("spot")), true)))
               ? ccxt::any(std::string("clientOrderId"))
               : ccxt::any(std::string("clOrdId")));
      ::setValue(request, clientOrderIdKey, clientOrderId);
      params = this->omit(params, ccxt::list{std::string("clientOrderId"),
                                             std::string("clOrdId")});
    }
    // remember the timestamp before issuing the request
    return ccxt::list{request, params};
  }

  /**
   * @method
   * @name poloniex#editOrder
   * @description edit a trade order
   * @see
   * https://api-docs.poloniex.com/spot/api/private/order#cancel-replace-order
   * @see
   * https://api-docs.poloniex.com/spot/api/private/smart-order#cancel-replace-order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} [amount] how much of the currency you want to trade in units
   * of the base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.triggerPrice] The price at which a trigger order is
   * triggered at
   * @param {string} [params.clientOrderId] a unique identifier for the order
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  editOrder(ccxt::any id, ccxt::any symbol, ccxt::any type, ccxt::any side,
            ccxt::any amount = ccxt::any{}, ccxt::any price = ccxt::any{},
            ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                     true))) {
                   throw NotSupported(toString(add(
                       add(add(this->id,
                               std::string(" editOrder() does not support ")),
                           ::getValue(market, std::string("type"))),
                       std::string(" orders, only spot orders are accepted"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("id"), id},
                 };
                 ccxt::any triggerPrice =
                     this->safeNumber2(params, std::string("stopPrice"),
                                       std::string("triggerPrice"));
                 ccxt::any requestparamsVariable = this->orderRequest(
                     symbol, type, side, amount, request, price, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = ccxt::dict{};
                 if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   response = awaitValue(this->privatePutSmartordersId(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(
                       this->privatePutOrdersId(this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "id" : "78923648051920896",
                 //         "clientOrderId" : ""
                 //     }
                 //
                 response =
                     this->extend(response, ccxt::dict{
                                                {std::string("side"), side},
                                                {std::string("type"), type},
                                            });
                 return this->parseOrder(response, market);
               })
        .share();
  }

  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 //
                 // @method
                 // @name poloniex#cancelOrder
                 // @description cancels an open order
                 // @see
                 // https://api-docs.poloniex.com/spot/api/private/order#cancel-order-by-id
                 // @see
                 // https://api-docs.poloniex.com/spot/api/private/smart-order#cancel-order-by-id
                 // // trigger orders
                 // @param {string} id order id
                 // @param {string} symbol unified symbol of the market the
                 // order was made in
                 // @param {object} [params] extra parameters specific to the
                 // exchange API endpoint
                 // @param {boolean} [params.trigger] true if canceling a
                 // trigger order
                 // @returns {object} An [order structure]{@link
                 // https://docs.ccxt.com/?id=order-structure}
                 //
                 awaitValue(this->loadMarkets());
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(
                       add(this->id,
                           std::string(
                               " cancelOrder() requires a symbol argument"))));
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(::getValue(market, std::string("spot")),
                                     true))) {
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                   ::setValue(request, std::string("ordId"), id);
                   ccxt::any raw =
                       awaitValue(this->swapPrivateDeleteV3TradeOrder(
                           this->extend(request, params)));
                   //
                   //    {
                   //        "code": "200",
                   //        "msg": "Success",
                   //        "data": {
                   //            "ordId": "418886099910612040",
                   //            "clOrdId": "polo418886099910612040"
                   //        }
                   //    }
                   //
                   return this->parseOrder(
                       this->safeDict(raw, std::string("data"), ccxt::dict{}));
                 }
                 ccxt::any clientOrderId =
                     this->safeValue(params, std::string("clientOrderId"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   id = clientOrderId;
                 }
                 ::setValue(request, std::string("id"), id);
                 ccxt::any isTrigger = this->safeValue2(
                     params, std::string("trigger"), std::string("stop"));
                 params =
                     this->omit(params, ccxt::list{std::string("clientOrderId"),
                                                   std::string("trigger"),
                                                   std::string("stop")});
                 ccxt::any response = ccxt::dict{};
                 if (isTrue(isEqual(isTrigger, true))) {
                   response = awaitValue(this->privateDeleteSmartordersId(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privateDeleteOrdersId(
                       this->extend(request, params)));
                 }
                 //
                 //   {
                 //       "orderId":"210832697138888704",
                 //       "clientOrderId":"",
                 //       "state":"PENDING_CANCEL",
                 //       "code":200,
                 //       "message":""
                 //   }
                 //
                 return this->parseOrder(response);
               })
        .share();
  }

  /**
   * @method
   * @name poloniex#cancelAllOrders
   * @description cancel all open orders
   * @see https://api-docs.poloniex.com/spot/api/private/order#cancel-all-orders
   * @see
   * https://api-docs.poloniex.com/spot/api/private/smart-order#cancel-all-orders
   * // trigger orders
   * @see https://api-docs.poloniex.com/v3/futures/api/trade/cancel-all-orders -
   * contract markets
   * @param {string} [symbol] unified market symbol, only orders in the market
   * of this symbol are cancelled when symbol is not undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] true if canceling trigger orders
   * @returns {object[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelAllOrders(ccxt::any symbol = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 ccxt::any request = ccxt::dict{
                     {std::string("symbols"), ccxt::list{}},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(
                       request, std::string("symbols"),
                       ccxt::list{::getValue(market, std::string("id"))});
                 }
                 ccxt::any response = ccxt::list{};
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("cancelAllOrders"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(
                         isTrue(isEqual(marketType, std::string("swap"))) ||
                         isTrue(isEqual(marketType, std::string("future"))))) {
                   ccxt::any raw =
                       awaitValue(this->swapPrivateDeleteV3TradeAllOrders(
                           this->extend(request, params)));
                   //
                   //    {
                   //        "code": "200",
                   //        "msg": "Success",
                   //        "data": [
                   //            {
                   //                "code": "200",
                   //                "msg": "Success",
                   //                "ordId": "418885787866388511",
                   //                "clOrdId": "polo418885787866388511"
                   //            }
                   //        ]
                   //    }
                   //
                   response =
                       this->safeList(raw, std::string("data"), ccxt::list{});
                   return this->parseOrders(response, market);
                 }
                 ccxt::any isTrigger = this->safeValue2(
                     params, std::string("trigger"), std::string("stop"));
                 params = this->omit(params, ccxt::list{std::string("trigger"),
                                                        std::string("stop")});
                 if (isTrue(isEqual(isTrigger, true))) {
                   response = awaitValue(this->privateDeleteSmartorders(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->privateDeleteOrders(
                       this->extend(request, params)));
                 }
                 //
                 //     [
                 //         {
                 //             "orderId" : "78xxxxxxxx80",
                 //             "clientOrderId" : "",
                 //             "state" : "NEW",
                 //             "code" : 200,
                 //             "message" : ""
                 //         }, {
                 //             "orderId" : "78xxxxxxxxx80",
                 //             "clientOrderId" : "",
                 //             "state" : "NEW",
                 //             "code" : 200,
                 //             "message" : ""
                 //         }
                 //     ]
                 //
                 return this->parseOrders(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name poloniex#fetchOrder
   * @description fetch an order by it's id
   * @see https://api-docs.poloniex.com/spot/api/private/order#order-details
   * @see https://api-docs.poloniex.com/spot/api/private/smart-order#open-orders
   * // trigger orders
   * @param {string} id order id
   * @param {string} symbol unified market symbol, default is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.trigger] true if fetching a trigger order
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 awaitValue(this->loadMarkets());
                 id = toString(id);
                 ccxt::any request = ccxt::dict{
                     {std::string("id"), id},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("fetchOrder"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(!isEqual(marketType, std::string("spot")))) {
                   throw NotSupported(toString(
                       add(add(add(this->id,
                                   std::string(
                                       " fetchOrder() is not supported for ")),
                               marketType),
                           std::string(" markets yet"))));
                 }
                 ccxt::any isTrigger = this->safeValue2(
                     params, std::string("trigger"), std::string("stop"));
                 params = this->omit(params, ccxt::list{std::string("trigger"),
                                                        std::string("stop")});
                 ccxt::any response = ccxt::dict{};
                 if (isTrue(isEqual(isTrigger, true))) {
                   response = awaitValue(this->privateGetSmartordersId(
                       this->extend(request, params)));
                   response = this->safeValue(response, 0);
                 } else {
                   response = awaitValue(
                       this->privateGetOrdersId(this->extend(request, params)));
                 }
                 //
                 //     {
                 //         "id": "21934611974062080",
                 //         "clientOrderId": "123",
                 //         "symbol": "TRX_USDC",
                 //         "state": "NEW",
                 //         "accountType": "SPOT",
                 //         "side": "SELL",
                 //         "type": "LIMIT",
                 //         "timeInForce": "GTC",
                 //         "quantity": "1.00",
                 //         "price": "10.00",
                 //         "avgPrice": "0.00",
                 //         "amount": "0.00",
                 //         "filledQuantity": "0.00",
                 //         "filledAmount": "0.00",
                 //         "stopPrice": "3750.00",              // for trigger
                 //         orders "createTime": 1646196019020, "updateTime":
                 //         1646196019020
                 //     }
                 //
                 ccxt::any order = this->parseOrder(response);
                 ::setValue(order, std::string("id"), id);
                 return order;
               })
        .share();
  }

  std::shared_future<ccxt::any>
  fetchOrderStatus(ccxt::any id, ccxt::any symbol = ccxt::any{},
                   ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        awaitValue(this->loadMarkets());
                        ccxt::any orders = awaitValue(this->fetchOpenOrders(
                            symbol, ccxt::any{}, ccxt::any{}, params));
                        ccxt::any indexed =
                            this->indexBy(orders, std::string("id"));
                        return (isTrue((inOp(indexed, id)))
                                    ? ccxt::any(std::string("open"))
                                    : ccxt::any(std::string("closed")));
                      })
        .share();
  }

